mod solution;

fn main() {
    let cases = [
    (r#"[2,3,7,8,10]"#, r#"true"#),
    (r#"[5,5]"#, r#"false"#),
    (r#"
[5,5]
"#, r#"false"#),
    (r#"  
[2,3,7,8,10]
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS subset-sum");
}
